import{z as B,x as l,o as e,c as p,q as i,j as o,D as E,d as t,s as n,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"时间序列动量 CTA","description":"","frontmatter":{"title":"时间序列动量 CTA","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cta-tsmom.md","filePath":"quant/cta-tsmom.md","lastUpdated":1791063341000}'),m={name:"quant/cta-tsmom.md"};function d(h,a,C,T,c,u){const A=l("Mermaid");return e(),p("div",null,[a[2]||(a[2]=i('<h1 id="时间序列动量-cta" tabindex="-1">时间序列动量 CTA <a class="header-anchor" href="#时间序列动量-cta" aria-label="Permalink to &quot;时间序列动量 CTA&quot;">​</a></h1><div class="epigraph"><p>若资产自己过去十二个月的超额收益为正，则做多；为负则做空；再按波动把仓位缩放到目标风险。管理期货把同一条规则写成可交易的跨品种组合。</p><footer>—— Moskowitz, Ooi &amp; Pedersen, Time Series Momentum, Journal of Financial Economics, 2012</footer></div><p><a href="/quant/ratio-sampling-error">上一课</a>停在业绩比率的噪声与技能分离。缺口换成宏观期货趋势产品。<a href="/quant/tsmom">时间序列动量</a> 写的是 MOP 的学术定义与检验。本篇把同一对象接到 <strong>CTA / 管理期货</strong>：流动期货池、多时间尺度、波动目标、换月与危机凸性如何被产品化。Hurst、Ooi 与 Pedersen 用一个世纪的趋势证据说明，这件事不是 1980 年代商品顾问的样本偶然；Baltas 与 Kosowski 一类工作则讨论容量、换手与波动缩放如何改写夏普。把 CTA 的宣传册直接贴上 2012 年论文的 t 值，或把论文的 12 个月符号当成业界唯一规则，都会错。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CTA 要回答的交易问题是：在股指、国债、商品、外汇期货上，要不要对每一份合约持有与其自身过去趋势同向的仓位，以及如何把几十上百份合约收成一个目标波动的组合。截面 <a href="/quant/momentum-wml">WML</a> 强制多空资金中性，不能在「所有市场都在跌」时变成净空头；TSMOM 可以，这正是管理期货被当成危机凸性来源的原因。问题是产品层还有三层摩擦：多尺度信号如何合成、波动缩放与组合风险平价如何嵌套、换月与冲击如何从纸面夏普里扣掉。</p><p>第二个问题是识别。均线金叉、唐奇安通道、12 个月符号，在月频上高度相关，但换手、滞后与在震荡市的磨损不同。学术 TSMOM 是干净的符号函数；CTA 是滤波器组。复制必须声明是在复制论文，还是在复制一种可投资的趋势组合。</p><h3 id="符号、均线与通道不是三个市场" tabindex="-1">符号、均线与通道不是三个市场 <a class="header-anchor" href="#符号、均线与通道不是三个市场" aria-label="Permalink to &quot;符号、均线与通道不是三个市场&quot;">​</a></h3><p>对资产 \\(i\\)，论文基准是</p> \\[w_{i,t}\\propto \\mathrm{sign}(r_{t-L,t}^{e,i})\\cdot\\frac{\\sigma_{\\mathrm{tgt}}}{\\hat\\sigma_{i,t}}. \\]<p>\\(L=12\\) 个月是主结果，1 到 12 个月通常都为正。价格与长均线的差、突破前高，在趋势状态里与 \\(\\mathrm{sign}\\) 同号，在来回穿越时更吵。CTA 常用 1 个月到 12 个月甚至更长的一组 \\(L\\)，按风险预算加权，为的是让慢信号在震荡里少翻、快信号在转折里少迟到。这改变的是路径与换手，不是「要不要时间序列动量」这一命题。把三个滤波器的样本内最优权重当成新 alpha，多半是同一条 TSMOM 的再参数化。</p><p><span class="marginnote">个股 CTA 与期货 CTA 不可比：借券、涨跌停与退市使空头腿残缺。MOP 与世纪趋势文献的主样本是流动期货。用小盘股票的时间序列动量去验证管理期货产品，是换了市场微观结构还在用同一张成绩单。</span></p><p><span class="marginnote">术语翻译：TSMOM 的核心规则翻译成大白话就是「这只品种过去一年涨了就持有多头，跌了就持有空头，涨得越颠簸（波动越大）拿得越少」。它不看财报、不看估值，只回答一个问题：这个市场自己最近在往哪边走，我顺不顺这个方向。</span></p><p><span class="marginnote">数字实例：设目标年化波动 12%，某原油期货 EWMA 估出年化波动 24%，则合约层仓位取 \\(\\sigma_{\\mathrm{tgt}}/\\hat\\sigma = 12/24 = 0.5\\) 倍名义；若波动降到 8%，仓位放大到 1.5 倍。同一段趋势，平静期拿得重、颠簸期拿得轻——这就是回测里「同样的信号、不同的仓位路径」的来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>资产池：流动性、合约规格、夜盘与交割规则要先入池，再谈信号。国内股指与商品另有持仓限额与交易限制，空头腿不是 CME 样本的平移。信号：至少报告单尺度 12 个月与多尺度合成两列；是否包含最近一日、是否跳月，期货上不如个股关键，但仍应固定。波动：EWMA 或 60 日左右已实现波动，目标波动先在合约层（论文常用较高的单资产目标再在组合层面对冲），再在组合层拉到产品波动（常见年化 10%–15% 一类）。组合权重接近等风险，而不是等名义，否则原油与天然气会吞掉汇率腿。</p><p>检验应对准 CTA 的使用场景：相对被动多头期货、相对截面动量、以及股权大跌窗口的平均收益（见<a href="/quant/crisis-alpha">危机 alpha</a>）。只交全样本夏普，无法区分「趋势溢价」与「碰巧做多了商品超级周期」。</p><h3 id="产品化时的三层杠杆" tabindex="-1">产品化时的三层杠杆 <a class="header-anchor" href="#产品化时的三层杠杆" aria-label="Permalink to &quot;产品化时的三层杠杆&quot;">​</a></h3><p>第一层是合约乘数与保证金，名义远大于权益。第二层是 vol targeting：\\(\\hat\\sigma\\) 低时加杠杆，高时去杠杆。第三层是组合再缩放，使总波动贴近产品说明书。三层同向时，平静期杠杆升得很高，一旦波动跳升，去杠杆本身成为市场供给，见<a href="/quant/crowding-spiral">拥挤与清盘螺旋</a>。回测若只在收益序列上乘一个常数杠杆，会漏掉第二层的路径依赖：同样的信号，在波动聚类里的仓位过程完全不同。</p>',18)),(e(),o(s,null,{default:E(()=>[n(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%90%84%E6%9C%9F%E8%B4%A7%E8%BF%87%E5%8E%BB%E8%B6%85%E9%A2%9D%22%5D%20--%3E%20S%5B%22%E5%8D%95%E5%B0%BA%E5%BA%A6%E6%88%96%E5%A4%9A%E5%B0%BA%E5%BA%A6%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20SIG%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%20%2F%20EWMA%20%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20W%5B%22%E5%90%88%E7%BA%A6%E4%BB%93%E4%BD%8D%20%E2%88%9D%20sign%20%2F%20%CF%83%22%5D%0A%20%20S%20--%3E%20W%0A%20%20W%20--%3E%20P%5B%22%E7%AD%89%E9%A3%8E%E9%99%A9%E5%90%88%E6%88%90%22%5D%0A%20%20P%20--%3E%20T%5B%22%E7%BB%84%E5%90%88%E6%B3%A2%E5%8A%A8%E7%9B%AE%E6%A0%87%22%5D%0A%20%20T%20--%3E%20CTA%5B%22TSMOM%20CTA%22%5D%0A%20%20ROLL%5B%22%E6%8D%A2%E6%9C%88%E4%B8%8E%E5%86%B2%E5%87%BB%22%5D%20--%3E%20CTA%0A%20%20CTA%20--%3E%20CRISIS%5B%22%E5%8D%B1%E6%9C%BA%E7%AA%97%E5%8F%A3%E8%AF%8A%E6%96%AD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"行为：消息渗入价格缓慢，趋势随后被仓位与止损强化，长期过度再反转。套保：商品生产商持续提供流动性给趋势一侧，部分解释商品样本，解释不了股指与汇率上同样存在的 TSMOM。风险预算：CTA 自己在波动上升时减仓，既减回撤，也可能在趋势加速的前段少赚。危机凸性来自「可以净空股指」，不是来自买入期权；V 型反转是对称的左尾。",-1)),(e(),o(s,null,{default:E(()=>[n(A,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20Shock%5B%22%E8%82%A1%E7%A5%A8%E5%B8%82%E5%9C%BA%E6%80%A5%E8%B7%8C%EF%BC%9A%E6%B3%A2%E5%8A%A8%E8%B7%B3%E5%8D%87%22%5D%20--%3E%20A%5B%22CTA%20%E7%A9%BA%E5%A4%B4%E8%82%A1%E6%8C%87%E8%85%BF%E5%BC%80%E5%A7%8B%E7%9B%88%E5%88%A9%22%5D%0A%20%20Shock%20--%3E%20B%5B%22vol%20target%20%E8%A7%A6%E5%8F%91%E5%85%A8%E7%BB%84%E5%90%88%E5%87%8F%E4%BB%93%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%8A%9B%E5%94%AE%E5%80%BA%E5%88%B8%E4%B8%8E%E5%95%86%E5%93%81%E5%A4%9A%E5%A4%B4%E8%85%BF%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%85%B6%E4%BB%96%20CTA%20%E5%90%8C%E8%A7%84%E5%88%99%E5%90%8C%E5%90%91%E5%87%8F%E4%BB%93%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%8B%A5%E6%8C%A4%E5%8E%BB%E6%9D%A0%E6%9D%86%E6%94%BE%E5%A4%A7%E4%BB%B7%E6%A0%BC%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20E%20--%3E%20B%0A%20%20A%20--%3E%20F%5B%22%E5%8D%B1%E6%9C%BA%E5%87%B8%E6%80%A7%EF%BC%9A%E5%87%80%E5%80%BC%E4%B8%8E%E8%82%A1%E7%A5%A8%E8%B4%9F%E7%9B%B8%E5%85%B3%22%5D%0A%20%20E%20-.-%3E%7C%22%E5%B7%A6%E5%B0%BE%EF%BC%9AV%20%E5%9E%8B%E5%8F%8D%E8%BD%AC%E6%97%B6%E5%9B%9E%E5%90%90%22%7C%20F%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>与 <a href="/quant/carry-everywhere">Carry</a> 的分工仍然成立：Carry 假定价格不变时的收入腿，TSMOM 用价格已经走的方向。CTA 若把曲线斜率与趋势乘在一起当单一信号，商品上会把展期算进动量，见<a href="/quant/trend-vs-roll">商品趋势与展期</a>。正确的产品设计是两条腿分开记账，相关有限时再合成。</p><h3 id="容量与拥挤改写的是执行-不是-t-值" tabindex="-1">容量与拥挤改写的是执行，不是 t 值 <a class="header-anchor" href="#容量与拥挤改写的是执行-不是-t-值" aria-label="Permalink to &quot;容量与拥挤改写的是执行，不是 t 值&quot;">​</a></h3><p>学术组合假设中间价成交。真实 CTA 在滚仓周、期权到期周、以及同业 vol target 触发日与深度抢同一侧。世纪样本里趋势很强的某些商品，当时并没有同等规模的管理期货。样本外应看：换手、参与率上限、以及信号在资产间已经高度同号时是否主动降总杠杆。夏普从论文到产品的衰减，优先用冲击与拥挤解释，而不是先去加第四个均线。</p><p><span class="marginnote">TSMOM 的净暴露随趋势变号，这是功能，不是 bug。向股权组合推销 CTA 时必须展示净暴露路径与最大回撤，而不是只展示「与股票低相关」的全样本数字——低相关来自时变空头，空头腿在政策反转里会亏。</span></p><p><span class="marginnote">常见误区：「CTA 的危机 alpha 是买看跌期权跌出来的」。实际上多数管理期货不买期权，凸性来自仓位自由变号：股票崩时趋势信号已翻空，空头股指期货在赚钱。代价同样真实——V 型反转日，刚建立的空腿被反弹打回，这是同一个机制的左尾，不能只要一半。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 12 个月均线金叉直接标注为 Moskowitz et al.（2012）。不要把个股 12−1 的截面 t 值写进期货 CTA 的尽调。不要在已经波动缩放之后，再用未缩放的多头指数当基准并声称「同等风险」。目标波动定高了，回撤按比例放大，信息没有增加。A 股股指期货的限制区间里，空头 CTA 不是国际样本的子集。</p><p>多尺度加权、通道与均线属于实施细节，应放进附录与换手表，不应当成独立「策略工厂」。与风险平价、股票动量同时持有时，股指腿会重复方向暴露，需在基金层面对冲或预算。</p><p><span class="marginnote">出处：Moskowitz, Ooi &amp; Pedersen, <em>Time Series Momentum</em>, Journal of Financial Economics, 2012。长样本趋势见 Hurst, Ooi &amp; Pedersen, <em>A Century of Evidence on Trend-Following Investing</em>。截面动量见 Jegadeesh &amp; Titman, 1993。CTA 危机表现见 Kaminski 的 crisis alpha 论述。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>管理期货的核心可交易规则与 TSMOM 一致：对自身过去超额取符号，再按波动缩放、跨资产分散。</li><li>多尺度、均线与通道是滤波器选择，月频上与 12 个月符号高度相关，差异主要在换手与转折路径。</li><li>危机凸性来自可净空的时变暴露，V 型反转与拥挤去杠杆是左尾。</li><li>产品夏普取决于换月、冲击、目标波动与容量，不是论文 t 值的常数倍。</li><li>出处：Moskowitz, Ooi &amp; Pedersen, JFE, 2012；Hurst, Ooi &amp; Pedersen 的长样本趋势证据。</li></ul>',11))])}const g=B(m,[["render",d]]);export{f as __pageData,g as default};
